@using sv_2bdaf323752d44679b9704d734411fdf.Models

<div class="step-form-section">
    <h4 class="mb-3">References</h4>
    <p class="text-muted">Please provide 2–3 professional references.</p>

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        var reference = References[index];

        <div class="card mb-3">
            <div class="card-body">
                <div class="d-flex justify-content-between align-items-center mb-3">
                    <h6 class="card-title mb-0">Reference @(index + 1)</h6>
                    @if (References.Count > 1)
                    {
                        <button type="button" class="btn btn-outline-danger btn-sm" @onclick="() => RemoveReference(index)">
                            <span>✕</span> Remove
                        </button>
                    }
                </div>

                <div class="row mb-2">
                    <div class="col-md-6">
                        <label class="form-label">Name <span class="text-danger">*</span></label>
                        <input type="text" class="form-control @(GetError(index, "Name") != null ? "is-invalid" : "")"
                               value="@reference.Name"
                               @onchange="e => UpdateReference(index, reference with { Name = e.Value?.ToString() ?? "" })" />
                        @if (GetError(index, "Name") is string nameErr)
                        {
                            <div class="invalid-feedback">@nameErr</div>
                        }
                    </div>
                    <div class="col-md-6">
                        <label class="form-label">Relationship <span class="text-danger">*</span></label>
                        <input type="text" class="form-control @(GetError(index, "Relationship") != null ? "is-invalid" : "")"
                               value="@reference.Relationship"
                               @onchange="e => UpdateReference(index, reference with { Relationship = e.Value?.ToString() ?? "" })" />
                        @if (GetError(index, "Relationship") is string relErr)
                        {
                            <div class="invalid-feedback">@relErr</div>
                        }
                    </div>
                </div>

                <div class="row mb-2">
                    <div class="col-md-6">
                        <label class="form-label">Email <span class="text-danger">*</span></label>
                        <input type="email" class="form-control @(GetError(index, "Email") != null ? "is-invalid" : "")"
                               value="@reference.Email"
                               @onchange="e => UpdateReference(index, reference with { Email = e.Value?.ToString() ?? "" })" />
                        @if (GetError(index, "Email") is string emailErr)
                        {
                            <div class="invalid-feedback">@emailErr</div>
                        }
                    </div>
                    <div class="col-md-6">
                        <label class="form-label">Phone <span class="text-danger">*</span></label>
                        <input type="tel" class="form-control @(GetError(index, "Phone") != null ? "is-invalid" : "")"
                               value="@reference.Phone"
                               @onchange="e => UpdateReference(index, reference with { Phone = e.Value?.ToString() ?? "" })" />
                        @if (GetError(index, "Phone") is string phoneErr)
                        {
                            <div class="invalid-feedback">@phoneErr</div>
                        }
                    </div>
                </div>
            </div>
        </div>
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn btn-outline-primary" @onclick="AddReference">
            <span>+</span> Add Reference
        </button>
    }
</div>

@code {
    [Parameter] public List<ReferenceModel> References { get; set; } = new();
    [Parameter] public EventCallback<List<ReferenceModel>> ReferencesChanged { get; set; }
    [Parameter] public Dictionary<string, string> Errors { get; set; } = new();

    public record ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }

    private void UpdateReference(int index, ReferenceModel updated)
    {
        References[index] = updated;
        ReferencesChanged.InvokeAsync(References);
    }

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new ReferenceModel());
            ReferencesChanged.InvokeAsync(References);
        }
    }

    private void RemoveReference(int index)
    {
        References.RemoveAt(index);
        ReferencesChanged.InvokeAsync(References);
    }

    private string? GetError(int index, string field)
    {
        var key = $"Ref[{index}].{field}";
        return Errors.TryGetValue(key, out var err) ? err : null;
    }
}

