            <div class="d-flex justify-content-between position-relative">
                @for (int i = 0; i < _stepLabels.Length; i++)
                {
                    var step = i + 1;
                    var isCurrent = step == _currentStep;
                    var isCompleted = _completedSteps.Contains(step);
                    var isFuture = step > _currentStep && !isCompleted;

                    <div class="step-item text-center flex-fill @(isCurrent ? "active" : "") @(isCompleted ? "completed" : "") @(isFuture ? "dimmed" : "")"
                         @onclick="() => GoToStep(step)"
                         style="cursor: @(isCompleted ? "pointer" : "default");"
                         role="button">
                        <div class="step-circle mx-auto mb-1 @(isCurrent ? "bg-primary text-white" : isCompleted ? "bg-success text-white" : "bg-light text-muted border")">
                            @if (isCompleted && !isCurrent)
                            {
                                <span>✓</span>
                            }
                            else
                            {
                                <span>@step</span>
                            }
                        </div>
                        <small class="@(isFuture ? "text-muted" : isCurrent ? "fw-bold text-primary" : "text-success")">
                            @_stepLabels[i]
                        </small>
                    </div>
                }
            </div>
            <div class="progress mt-2" style="height: 4px;">
                <div class="progress-bar" role="progressbar"
                     style="width: @((_currentStep - 1) * 25)%"></div>
            </div>
        </nav>

        @* Validation summary *@
        @if (!string.IsNullOrEmpty(_errorSummary))
        {
            <div class="alert alert-danger" role="alert">@_errorSummary</div>
        }

        @* Step Content *@
        @switch (_currentStep)
        {
            case 1:
                <StepPersonalInfo FullName="@_fullName" FullNameChanged="v => _fullName = v"
                                  Email="@_email" EmailChanged="v => _email = v"
                                  Phone="@_phone" PhoneChanged="v => _phone = v"
                                  Address="@_address" AddressChanged="v => _address = v"
                                  Errors="_fieldErrors" />
                break;
            case 2:
                <StepWorkHistory Entries="_workEntries" EntriesChanged="v => _workEntries = v"
                                 Errors="_fieldErrors" />
                break;
            case 3:
                <StepReferences References="_references" ReferencesChanged="v => _references = v"
                                Errors="_fieldErrors" />
                break;
            case 4:
                <StepCoverLetter CoverLetter="@_coverLetter" CoverLetterChanged="v => _coverLetter = v"
                                 Errors="_fieldErrors" />
                break;
            case 5:
                <StepReview FullName="@_fullName" Email="@_email" Phone="@_phone" Address="@_address"
                            WorkEntries="_workEntries" References="_references"
                            CoverLetter="@_coverLetter" OnEditStep="GoToStep" />
                break;
        }

        @* Navigation Buttons *@
        <div class="d-flex justify-content-between mt-4">
            <div>
                @if (_currentStep > 1)
                {
                    <button type="button" class="btn btn-outline-secondary" @onclick="GoBack" disabled="@_isProcessing">
                        ← Back
                    </button>
                }
            </div>
            <div>
                @if (_currentStep < 5)
                {
                    <button type="button" class="btn btn-primary" @onclick="GoNext" disabled="@_isProcessing">
                        @if (_isProcessing)
                        {
                            <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                            <span>Validating...</span>
                        }
                        else
                        {
                            <span>Next →</span>
                        }
                    </button>
                }
                else
                {
                    <button type="button" class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@_isProcessing">
                        @if (_isProcessing)
                        {
                            <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                            <span>Submitting...</span>
                        }
                        else
                        {
                            <span>Submit Application</span>
                        }
                    </button>
                }
            </div>
        </div>
    }
    else
    {
        @* Submission Confirmation *@
        <div class="text-center py-5">
            <div class="mb-3" style="font-size: 4rem;">✅</div>
            <h3 class="text-success mb-3">Application Submitted!</h3>
            <p class="lead">Thank you, <strong>@_fullName</strong>. Your application has been received.</p>
            <div class="alert alert-info d-inline-block">
                Your Application ID: <strong>#@_applicationId</strong>
            </div>
            <p class="text-muted mt-3">Please save this ID for your records. We'll be in touch at <strong>@_email</strong>.</p>
        </div>
    }
</div>

@code {
    private static readonly string[] _stepLabels = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private int _currentStep = 1;
    private readonly HashSet<int> _completedSteps = new();
    private bool _isProcessing;
    private bool _submitted;
    private int _applicationId;
    private string _errorSummary = "";
    private Dictionary<string, string> _fieldErrors = new();

    // Step 1 state
    private string _fullName = "";
    private string _email = "";
    private string _phone = "";
    private string _address = "";

    // Step 2 state
    private List<StepWorkHistory.WorkEntryModel> _workEntries = new() { new() };

    // Step 3 state
    private List<StepReferences.ReferenceModel> _references = new() { new(), new() };

    // Step 4 state
    private string _coverLetter = "";

    private void GoToStep(int step)
    {
        if (_completedSteps.Contains(step) || step == _currentStep)
        {
            _fieldErrors.Clear();
            _errorSummary = "";
            _currentStep = step;
        }
    }

    private void GoBack()
    {
        if (_currentStep > 1)
        {
            _fieldErrors.Clear();
            _errorSummary = "";
            _currentStep--;
        }
    }

    private async Task GoNext()
    {
        _fieldErrors.Clear();
        _errorSummary = "";

        if (!await ValidateCurrentStep())
            return;

        _completedSteps.Add(_currentStep);
        _currentStep++;
    }

    private async Task<bool> ValidateCurrentStep()
    {
        _isProcessing = true;
        try
        {
            switch (_currentStep)
            {
                case 1:
                    return await ValidatePersonalInfo();
                case 2:
                    return ValidateWorkHistory();
                case 3:
                    return ValidateReferences();
                case 4:
                    return ValidateCoverLetter();
                default:
                    return true;
            }
        }
        finally
        {
            _isProcessing = false;
        }
    }

    private async Task<bool> ValidatePersonalInfo()
    {
        if (string.IsNullOrWhiteSpace(_fullName))
            _fieldErrors["FullName"] = "Full name is required.";
        if (string.IsNullOrWhiteSpace(_email))
            _fieldErrors["Email"] = "Email is required.";
        if (string.IsNullOrWhiteSpace(_phone))
            _fieldErrors["Phone"] = "Phone number is required.";
        if (string.IsNullOrWhiteSpace(_address))
            _fieldErrors["Address"] = "Address is required.";

        if (_fieldErrors.Count > 0)
        {
            _errorSummary = "Please fill in all required fields.";
            return false;
        }

        var emailValid = await ApplicationService.ValidateEmailAsync(_email);
        if (!emailValid)
        {
            _fieldErrors["Email"] = "Please enter a valid email address.";
            _errorSummary = "Email validation failed.";
            return false;
        }

        return true;
    }

    private bool ValidateWorkHistory()
    {
        for (int i = 0; i < _workEntries.Count; i++)
        {
            var entry = _workEntries[i];
            if (string.IsNullOrWhiteSpace(entry.Company))
                _fieldErrors[$"Work[{i}].Company"] = "Company name is required.";
            if (string.IsNullOrWhiteSpace(entry.Title))
                _fieldErrors[$"Work[{i}].Title"] = "Job title is required.";
            if (entry.StartDate == default)
                _fieldErrors[$"Work[{i}].StartDate"] = "Start date is required.";
        }

        if (_fieldErrors.Count > 0)
        {
            _errorSummary = "Please complete all required fields for each position.";
            return false;
        }
        return true;
    }

    private bool ValidateReferences()
    {
        for (int i = 0; i < _references.Count; i++)
        {
            var r = _references[i];
            if (string.IsNullOrWhiteSpace(r.Name))
                _fieldErrors[$"Ref[{i}].Name"] = "Name is required.";
            if (string.IsNullOrWhiteSpace(r.Relationship))
                _fieldErrors[$"Ref[{i}].Relationship"] = "Relationship is required.";
            if (string.IsNullOrWhiteSpace(r.Email))
                _fieldErrors[$"Ref[{i}].Email"] = "Email is required.";
            if (string.IsNullOrWhiteSpace(r.Phone))
                _fieldErrors[$"Ref[{i}].Phone"] = "Phone is required.";
        }

        if (_fieldErrors.Count > 0)
        {
            _errorSummary = "Please complete all required fields for each reference.";
            return false;
        }
        return true;
    }

    private bool ValidateCoverLetter()
    {
        if (string.IsNullOrWhiteSpace(_coverLetter))
        {
            _fieldErrors["CoverLetter"] = "Cover letter is required.";
            _errorSummary = "Please write a cover letter.";
            return false;
        }
        if (_coverLetter.Length > 2000)
        {
            _fieldErrors["CoverLetter"] = "Cover letter must be 2000 characters or fewer.";
            _errorSummary = "Cover letter is too long.";
            return false;
        }
        return true;
    }

    private async Task SubmitApplication()
    {
        _isProcessing = true;
        _errorSummary = "";

        try
        {
            var application = new JobApplication(
                new PersonalInfo(_fullName, _email, _phone, _address),
                new WorkHistory(_workEntries.Select(e =>
                    new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList()),
                _references.Select(r =>
                    new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
                _coverLetter
            );

            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
            _submitted = true;
        }
        catch (Exception ex)
        {
            _errorSummary = $"Submission failed: {ex.Message}. Please try again.";
        }
        finally
        {
            _isProcessing = false;
        }
    }
}

