<div class="step-form-section">
    <h4 class="mb-3">Work History</h4>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        var entry = Entries[index];

        <div class="card mb-3">
            <div class="card-body">
                <div class="d-flex justify-content-between align-items-center mb-3">
                    <h6 class="card-title mb-0">Position @(index + 1)</h6>
                    @if (Entries.Count > 1)
                    {
                        <button type="button" class="btn btn-outline-danger btn-sm" @onclick="() => RemoveEntry(index)">
                            <span>✕</span> Remove
                        </button>
                    }
                </div>

                <div class="row mb-2">
                    <div class="col-md-6">
                        <label class="form-label">Company Name <span class="text-danger">*</span></label>
                        <input type="text" class="form-control @(GetError(index, "Company") != null ? "is-invalid" : "")"
                               value="@entry.Company"
                               @onchange="e => SetField(index, nameof(WorkEntryModel.Company), e)" />
                        @if (GetError(index, "Company") is string compErr)
                        {
                            <div class="invalid-feedback">@compErr</div>
                        }
                    </div>
                    <div class="col-md-6">
                        <label class="form-label">Job Title <span class="text-danger">*</span></label>
                        <input type="text" class="form-control @(GetError(index, "Title") != null ? "is-invalid" : "")"
                               value="@entry.Title"
                               @onchange="e => SetField(index, nameof(WorkEntryModel.Title), e)" />
                        @if (GetError(index, "Title") is string titleErr)
                        {
                            <div class="invalid-feedback">@titleErr</div>
                        }
                    </div>
                </div>

                <div class="row mb-2">
                    <div class="col-md-4">
                        <label class="form-label">Start Date <span class="text-danger">*</span></label>
                        <input type="date" class="form-control @(GetError(index, "StartDate") != null ? "is-invalid" : "")"
                               value="@(entry.StartDate == default ? "" : entry.StartDate.ToString("yyyy-MM-dd"))"
                               @onchange="e => SetField(index, nameof(WorkEntryModel.StartDate), e)" />
                        @if (GetError(index, "StartDate") is string startErr)
                        {
                            <div class="invalid-feedback">@startErr</div>
                        }
                    </div>
                    <div class="col-md-4">
                        <label class="form-label">End Date</label>
                        <input type="date" class="form-control"
                               value="@(entry.EndDate.HasValue ? entry.EndDate.Value.ToString("yyyy-MM-dd") : "")"
                               disabled="@entry.IsCurrent"
                               @onchange="e => SetField(index, nameof(WorkEntryModel.EndDate), e)" />
                    </div>
                    <div class="col-md-4 d-flex align-items-end">
                        <div class="form-check mb-2">
                            <input class="form-check-input" type="checkbox" id="@($"current-{index}")"
                                   checked="@entry.IsCurrent"
                                   @onchange="e => SetField(index, nameof(WorkEntryModel.IsCurrent), e)" />
                            <label class="form-check-label" for="@($"current-{index}")">Currently working here</label>
                        </div>
                    </div>
                </div>

                <div class="mb-2">
                    <label class="form-label">Description</label>
                    <textarea class="form-control" rows="2"
                              value="@entry.Description"
                              @onchange="e => SetField(index, nameof(WorkEntryModel.Description), e)"></textarea>
                </div>
            </div>
        </div>
    }

    <button type="button" class="btn btn-outline-primary" @onclick="AddEntry">
        <span>+</span> Add Another Position
    </button>
</div>

@code {
    [Parameter] public List<WorkEntryModel> Entries { get; set; } = new();
    [Parameter] public EventCallback<List<WorkEntryModel>> EntriesChanged { get; set; }
    [Parameter] public Dictionary<string, string> Errors { get; set; } = new();

    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }

    private void SetField(int index, string field, ChangeEventArgs e)
    {
        var entry = Entries[index];
        var val = e.Value?.ToString() ?? "";
        switch (field)
        {
            case nameof(WorkEntryModel.Company): entry.Company = val; break;
            case nameof(WorkEntryModel.Title): entry.Title = val; break;
            case nameof(WorkEntryModel.StartDate):
                entry.StartDate = DateTime.TryParse(val, out var sd) ? sd : default;
                break;
            case nameof(WorkEntryModel.EndDate):
                entry.EndDate = DateTime.TryParse(val, out var ed) ? ed : null;
                break;
            case nameof(WorkEntryModel.IsCurrent):
                entry.IsCurrent = e.Value is true;
                if (entry.IsCurrent) entry.EndDate = null;
                break;
            case nameof(WorkEntryModel.Description): entry.Description = val; break;
        }
        EntriesChanged.InvokeAsync(Entries);
    }

    private void AddEntry()
    {
        Entries.Add(new WorkEntryModel());
